import sys; sys.path.insert(0,'/workspace/work')
from analyze import *
import numpy as np
rowdur=0.125
def peaks(name, rows=16, inst_dur=None):
    d,sr=load('/workspace/work/e_%s.wav'%name)
    out=[]
    for r in range(rows):
        a=int(r*rowdur*sr); b=int((r+1)*rowdur*sr)
        if a>=d.shape[0]: break
        x=d[a:b,0]
        out.append('r%-2d %.3f/%.3f'%(r, amp(x), amp(d[a:b,1])))
    print('=== %s  len=%.2f'%(name,d.shape[0]/sr))
    print('   '+' | '.join(out[:8]))
    if len(out)>8: print('   '+' | '.join(out[8:]))
for n in ['off9','cut','delay','fporta','fvs','retrig9','retrig27','keyoff','brk','jump','tempo','gvol16','vvslide','pvslide','fvib','extpan','trem','ploop','gvslide','v80','vibctl']:
    peaks(n, rows=16 if n not in ('retrig9','retrig27','v80','extpan','keyoff','gvol16','ploop','vibctl') else 8)
EOF"}

