import wave, numpy as np, glob, os, re
def zcpitch(x,sr):
    x=x-np.mean(x); 
    zc=np.where(np.diff(np.sign(x))>0)[0]
    ts=[]
    for i in zc:
        y0,y1=x[i],x[i+1]
        if y1!=y0: ts.append(i+(-y0)/(y1-y0))
    ts=np.array(ts)
    if len(ts)<2: return None
    per=np.diff(ts); per=per[(per>0)&(per<sr/40)]
    if len(per)==0: return None
    return sr/np.median(per)
print("== relative_note sweep, note C-5(61) ==")
for rel in [0,-12,-6,-1,1,6,12]:
    f='/workspace/work/c_r%03d.wav'%(rel+100)
    w=wave.open(f); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
    d=d.reshape(-1,2); sr=w.getframerate()
    row=sr*60/150/6
    x=d[int(0.02*row):int(0.9*row),0]
    print('rel=%-4d pitch=%8.2f amp=%.3f  total_len=%.2f'%(rel, zcpitch(x,sr) or 0, np.abs(x).max(), d.shape[0]/sr))
print("== note sweep ==")
for note in [49,55,60,61,72,85]:
    for rel in [0,-12,12]:
        f='/workspace/work/c_n%d_%d.wav'%(note,rel+100)
