CHORDS=[('A3',('A3','C4','E4')),('F2',('F3','A3','C4')),('C3',('C3','E3','G3')),('G2',('G3','B3','D4'))]
ROOTS=['A2','F2','C3','G2']
PADCH=[('A3',('A3','C4','E4')),('F3',('F3','A3','C4')),('C4',('C3','E3','G3')),('G3',('G3','B3','D4'))]
BASSN=['A2','F2','C3','G2']

def drums(pat,bar0,style='full',fill=False):
    for b in range(4):
        r0=bar0+b*BAR
        kick=[0,6,10] if style!='half' else [0]
        if style=='intro': kick=[0,14]
        if fill and b==3: kick=[0,6,8,10,12]
        for r in kick: put(pat,r0+r,K_,note=49,inst=K,vol=64)
        if style!='intro':
            for r in (4,12): put(pat,r0+r,SN_,note=49,inst=SN,vol=58)
            for r in (12,): put(pat,r0+r,CL_,note=49,inst=CL,vol=44)
        # hats: 8ths with accent pattern
        for r in range(0,BAR,2):
            v=44 if r%4==0 else 30
            put(pat,r0+r,HAT_,note=49,inst=HAT,vol=v)
        if style in ('full','climax'):
            for r in (7,15): put(pat,r0+r,HAT_,note=49,inst=HAT,vol=22)
        if b==3: put(pat,r0+14,OH_,note=49,inst=OH,vol=36)
        if fill and b==3:
            for i,r in enumerate((10,11,12,13,14,15)):
                put(pat,r0+r,TM_,note=49+ [0,3,7,10,12,15][i],inst=TM,vol=48)
K_=0;SN_=1;CL_=2;HAT_=3;OH_=4;BS_=5;SUB_=6;LD_=7;LD2_=8;CH_=9;PL_=10;PL2_=11;PD1_=12;PD2_=13;ST_=14;RS_=15

def bassline(pat,bar0,roots=None,pattern=None):
    roots=roots or BASSN
    for b in range(4):
        r0=bar0+b*BAR; rt=roots[b]
        idx={'A2':0,'F2':0,'C3':0,'G2':0}
        seq(pat,BS_,r0,[(0,rt,{'inst':BS,'vol':62}),(3,rt,{'inst':BS,'vol':44}),(6,rt,{'inst':BS,'vol':56}),
                        (8,rt,{'inst':BS,'vol':50}),(10,rt,{'inst':BS,'vol':44}),(11,rt,{'inst':BS,'vol':58}),
                        (14,rt,{'inst':BS,'vol':52})])
        oct_up = N(rt)+12
        put(pat,r0+13,BS_,note=oct_up,inst=BS,vol=40)
        put(pat,r0,SUB_,note=N(rt),inst=SUB,vol=50)

def pad(pat,bar0,chords=None):
    chords=chords or PADCH
    for b in range(4):
        r0=bar0+b*BAR; root,tri=chords[b]
        put(pat,r0,PD1_,note=N(root),inst=PD1,vol=40)
        put(pat,r0,PD2_,note=N(tri[1]),inst=PD2,vol=36)
        put(pat,r0+1,PD1_,note=N(tri[2]),inst=PD1)   # extra voice same channel? use chord chan
        put(pat,r0+BAR-2,PD1_,eff=20,param=0)
        put(pat,r0+BAR-2,PD2_,eff=20,param=0)

# ---------------- melodies ----------------
VIB={'eff':4,'param':0x84}
def melodyA(pat,bar0,oct_=0):
    # 4-bar phrase over Am F C G, 16th grid
    bars=[
      [(0,'E4'),(2,'A4'),(4,'C5'),(6,'E5'),(8,'D5'),(10,'C5'),(12,'B4'),(14,'A4')],
      [(0,'A4'),(2,'C5'),(4,'F4'),(6,'A4'),(8,'C5'),(12,'A4'),(14,'G4')],
      [(0,'G4'),(2,'C5'),(4,'E5'),(6,'G5'),(8,'E5'),(10,'C5'),(12,'D5'),(14,'E5')],
      [(0,'D5'),(2,'B4'),(4,'G4'),(6,'B4'),(8,'D5'),(10,'B4'),(12,'G4'),(14,'F#4')],
    ]
    for b in range(4):
        r0=bar0+b*BAR
        for (r,n) in bars[b]:
            put(pat,r0+r,LD_,note=N(n)+oct_,inst=LD,vol=58,eff=4 if r in (0,) else None,param=0x84 if r in (0,) else None)
def melodyA2(pat,bar0):
    # harmony line a third below on LD2
    bars=[
      [(0,'C4'),(4,'E4'),(8,'A4'),(12,'G4')],
      [(0,'F4'),(4,'A4'),(8,'C5'),(12,'F4')],
      [(0,'E4'),(4,'G4'),(8,'C5'),(12,'G4')],
      [(0,'B3'),(4,'D4'),(8,'G4'),(12,'D4')],
    ]
    for b in range(4):
        r0=bar0+b*BAR
        for (r,n) in bars[b]:
            put(pat,r0+r,LD2_,note=N(n),inst=LD2,vol=44,eff=4,param=0x63)

def arp(pat,bar0,root_list=None,inst=PL,ch=PL_,vol=46,dens=2):
    root_list=root_list or ['A3','F3','C4','G3']
    scales={'A3':[0,3,7,12,15,19,24,15,12,7,3],'F3':[0,4,7,12,16,19,24,19,16,12,7],
            'C4':[0,4,7,12,16,19,24,19,16,12,7],'G3':[0,4,7,11,14,19,23,19,14,11,7]}
    for b in range(4):
        r0=bar0+b*BAR; rt=root_list[b]; base=N(rt); sc=scales[rt]
        i=0
        for r in range(0,BAR,dens):
            put(pat,r0+r,ch,note=base+sc[i%len(sc)],inst=inst,vol=vol if i%4==0 else vol-8)
            i+=1

def chipmel(pat,bar0):
    bars=[
      [(0,'A5'),(2,'A5'),(3,'C6'),(4,'E6'),(6,'D6'),(8,'C6'),(10,'A5'),(12,'G5'),(14,'A5')],
      [(0,'F5'),(2,'A5'),(4,'C6'),(6,'F6'),(8,'E6'),(10,'C6'),(12,'A5'),(14,'C6')],
      [(0,'G5'),(2,'C6'),(4,'E6'),(6,'G6'),(8,'E6'),(10,'C6'),(12,'D6'),(14,'E6')],
      [(0,'D6'),(2,'B5'),(4,'G5'),(6,'D6'),(8,'B5'),(10,'G5'),(12,'A5'),(14,'B5')],
    ]
    for b in range(4):
        r0=bar0+b*BAR
        for (r,n) in bars[b]:
            put(pat,r0+r,CH_,note=N(n),inst=CH,vol=48,eff=0 if b in (1,3) else None,param=0x37 if b in (1,3) else None)

def stabs(pat,bar0):
    for b in range(4):
        r0=bar0+b*BAR; root,tri=PADCH[b]
        for off in (0,3,8,11):
            put(pat,r0+off,ST_,note=N(tri[1]),inst=ST,vol=46)
            put(pat,r0+off,PD2_,note=N(tri[2]),inst=ST,vol=30)

# ---------------- sections ----------------
def P_intro(p):
    put(p,0,RS_,note=49,inst=RS,vol=52)
    put(p,0,IM_,note=49,inst=IM,vol=54)
    pad(p,0)
    for r in (0,8,16,24,32,40,48,56): put(p,r,HAT_,note=49,inst=HAT,vol=26 if r%16 else 34)
    for i,r in enumerate((48,52,54,56,58,60,62)):
        put(p,r,K_,note=49,inst=K,vol=40+i*3)
    put(p,60,RS_,note=49,inst=RS,vol=40)
    put(p,63,SN_,note=49,inst=SN,vol=50); put(p,63,CL_,note=49,inst=CL,vol=44)
    arp(p,0,vol=30,dens=4)
def P_build(p):
    drums(p,0,style='intro'); bassline(p,0)
    arp(p,0,vol=38,dens=2); put(p,0,IM_,note=49,inst=IM,vol=46)
    pad(p,0)
    for r in range(32,64,2): put(p,r,HAT_,note=49,inst=HAT,vol=24+(r-32)//4)
    put(p,62,SN_,note=49,inst=SN,vol=54); put(p,63,SN_,note=49,inst=SN,vol=58)
def P_A1(p):
    drums(p,0,style='full'); bassline(p,0); melodyA(p,0); arp(p,0,vol=40,dens=4,inst=PL2,ch=PL2_)
    for b in range(4): put(p,b*BAR,PD1_,note=N(PADCH[b][0]),inst=PD1,vol=30)
    put(p,0,ST_,note=N('A4'),inst=ST,vol=44)
def P_A2(p):
    drums(p,0,style='full',fill=True); bassline(p,0); melodyA(p,0); melodyA2(p,0)
    arp(p,0,vol=42,dens=2,inst=PL,ch=PL_)
    stabs(p,0)
def P_break(p):
    pad(p,0); arp(p,0,vol=44,dens=2,inst=PL,ch=PL_); arp(p,0,vol=32,dens=2,inst=PL2,ch=PL2_,
        root_list=['A4','F4','C5','G4'])
    for b in range(4):
        r0=b*BAR; root,tri=PADCH[b]
        put(p,r0,SUB_,note=N(root),inst=SUB,vol=48)
    put(p,0,IM_,note=49,inst=IM,vol=40)
    for r in (0,16,32,48): put(p,r,LD_,note=None)
    # sparse melody
    for (r,n) in [(0,'E5'),(6,'C5'),(16,'A4'),(22,'F4'),(32,'G4'),(38,'E5'),(48,'D5'),(54,'B4')]:
        put(p,r,LD_,note=N(n),inst=LD,vol=48,eff=4,param=0x63)
def P_build2(p):
    drums(p,0,style='half'); bassline(p,0); arp(p,0,vol=40,dens=1)
    put(p,0,RS_,note=49,inst=RS,vol=48)
    for b in range(4):
        r0=b*BAR; put(p,r0,PD1_,note=N(PADCH[b][0]),inst=PD1,vol=34); put(p,r0+14,PD1_,eff=20,param=0)
    for i,r in enumerate(range(48,64)):
        if r%2==0: put(p,r,SN_,note=49,inst=SN,vol=30+i)
    put(p,63,IM_,note=49,inst=IM,vol=0)
def P_B1(p):
    drums(p,0,style='full'); bassline(p,0); chipmel(p,0)
    arp(p,0,vol=36,dens=2,inst=PL2,ch=PL2_)
    for b in range(4): put(p,b*BAR,PD1_,note=N(PADCH[b][0]),inst=PD1,vol=28)
def P_B2(p):
    drums(p,0,style='full',fill=True); bassline(p,0); chipmel(p,0); melodyA2(p,0)
    stabs(p,0)
def P_climax(p):
    drums(p,0,style='climax',fill=True); bassline(p,0); melodyA(p,0); melodyA2(p,0); chipmel(p,0)
    arp(p,0,vol=42,dens=1,inst=PL,ch=PL_); stabs(p,0)
    put(p,0,IM_,note=49,inst=IM,vol=58)
def P_outro(p):
    put(p,0,IM_,note=49,inst=IM,vol=56)
    drums(p,0,style='half'); bassline(p,0,roots=['A2','A2','F2','G2'])
    for b,rt in enumerate(['A2','A2','F2','G2']):
        r0=b*BAR; put(p,r0,PD1_,note=N('A3'),inst=PD1,vol=36); put(p,r0,PD2_,note=N('C4'),inst=PD2,vol=32)
        put(p,r0+12,PD1_,eff=20,param=0); put(p,r0+12,PD2_,eff=20,param=0)
    put(p,32,LD_,note=N('A5'),inst=LD,vol=56,eff=4,param=0x84)
    put(p,46,LD_,note=N('E5'),inst=LD,vol=48)
    put(p,56,SN_,note=49,inst=SN,vol=54); put(p,58,SN_,note=49,inst=SN,vol=50)
    put(p,60,CL_,note=49,inst=CL,vol=48); put(p,60,K_,note=49,inst=K,vol=60)
    put(p,60,PD1_,eff=20,param=0); put(p,60,PD2_,eff=20,param=0)

SECT=[P_intro,P_build,P_A1,P_A2,P_break,P_build2,P_B1,P_B2,P_climax,P_outro]
ORDER=[0,1,2,3,2,3,4,5,6,7,6,7,8,8,3,9]

