LOOPPAD=(5292,110250); LOOPSUS=(2205,66150)
INSTR=[
 (I_K,'kick.wav',128,64,0),(I_SN,'snare.wav',118,60,0),(I_CL,'clap.wav',140,52,0),(I_HAT,'hat.wav',168,42,0),
 (I_OH,'ohat.wav',86,40,0),(I_BS,'bass.wav',128,62,0),(I_SUB,'sub.wav',128,56,0),(I_LD,'lead.wav',150,60,0),
 (I_LD2,'lead.wav',100,40,0),(I_CH,'chip.wav',128,46,0),(I_PL,'pluck.wav',68,46,0),(I_PL2,'pluck.wav',188,38,0),
 (I_PD1,'pad.wav',58,38,LOOPPAD),(I_PD2,'pad.wav',198,34,LOOPPAD),(I_ST,'stab.wav',128,48,0),
 (I_RS,'riser.wav',128,46,0),(I_IM,'impact.wav',128,58,0),(I_TM,'tom.wav',128,50,0),(I_SUS,'sus.wav',128,54,LOOPSUS),
]
VIB={'eff':4,'param':0x84}
# harmony: Am | F | C | G
PROG=[('A',('A3','C4','E4'),('A2','F2','C3','G2')),]
